{
  "schema_version": "2.0",
  "checklist_id": "FC-BEI-001",
  "record_id": "BEI-001",
  "hypotheses": [
    {
      "hypothesis_id": "H1",
      "candidate_status": "candidate",
      "assumptions": [
        "The editor edits the intended locus in the intended cells at measurable fractions.",
        "Randomization, masking, and batch-balanced processing operate as declared."
      ],
      "boundary_conditions": [
        "Aged mice of one strain and sex mix over the prespecified horizon."
      ],
      "falsifier": {
        "prediction_id": "P1",
        "conditions": "Manipulation and measurement checks pass; precision sufficient to distinguish arm patterns.",
        "observable": "Within-animal on-target editing fraction and prespecified immune-competence outcome by arm.",
        "incompatible_result": "Improvement reproduces in vehicle-only or inert-locus arms at similar magnitude, or confirmed on-target editing shows no dose-response relation.",
        "assumption_failure_checks": [
          "Verify editing above assay detection in responder animals before interpreting incompatibility.",
          "Verify vehicle and inert-locus arms received identical handling and confirmed non-editing at the target locus."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT1",
          "rival_hypothesis_id": "H2",
          "focal_expected": "Active arm improves over vehicle-only and inert-locus arms; improvement tracks editing fraction; no procedure-linked shift in the negative-control outcome.",
          "rival_expected": "Vehicle-only and inert-locus arms improve similarly; no editing-fraction relation.",
          "indeterminate_result": "Both an editing-linked and a vehicle-linked component present; estimate both and declare the mixed mechanism."
        },
        {
          "test_id": "DT2",
          "rival_hypothesis_id": "H4",
          "focal_expected": "Contrast stable across acquisition batches; paired aliquots agree within repeatability.",
          "rival_expected": "Contrast flips or shrinks with batch; paired aliquots disagree beyond repeatability.",
          "indeterminate_result": "Batch variance too large relative to contrast to decide; reprocess before interpreting."
        },
        {
          "test_id": "DT3",
          "rival_hypothesis_id": "H5",
          "focal_expected": "Contrast persists under baseline adjustment, cage random effects, and ITT with prespecified exclusions.",
          "rival_expected": "Contrast collapses under adjustment or is carried by excluded or surviving animals.",
          "indeterminate_result": "Exclusions interactivewith arm under the ledger; report both ITT and per-protocol without selection."
        },
        {
          "test_id": "DT4",
          "rival_hypothesis_id": "H6",
          "focal_expected": "Functional competence endpoints improve following confirmed editing, not only subset panels.",
          "rival_expected": "Subset panels shift while functional endpoints stay unchanged.",
          "indeterminate_result": "Horizon too short for functional endpoints; extend the schedule rather than claim restoration."
        },
        {
          "test_id": "DT5",
          "rival_hypothesis_id": "H3",
          "focal_expected": "Response tracks on-target fraction; off-target burden low and uncorrelated.",
          "rival_expected": "Response tracks off-target burden at a plausible locus or cell type.",
          "indeterminate_result": "Both correlate; locus-level causal follow-up required before mechanism language."
        }
      ],
      "nulls": [
        {
          "null_id": "N1",
          "statement": "The population mean change in the primary immune-competence outcome is equal between the active-editor and inert-locus-editor arms at the prespecified horizon.",
          "analysis_id": "A1",
          "interpretation_limit": "Failure to reject is not equivalence, absence of effect, or proof of a rival."
        }
      ],
      "controls": [
        {
          "control_id": "NC-PROCEDURE",
          "control_type": "negative_outcome",
          "rationale": "A readout the proposed on-target mechanism cannot touch but that shares the injection, sampling, and processing workflow.",
          "expected_result": "No arm-linked difference in the negative-control outcome.",
          "failure_implication": "Investigate procedure, selection, or analysis bias before any causal interpretation."
        },
        {
          "control_id": "NC-QC",
          "control_type": "negative_outcome",
          "rationale": "Spike-in reference beads ride every acquisition run but cannot respond to the edit.",
          "expected_result": "Beads within locked tolerance across arms and batches.",
          "failure_implication": "Acquisition quality failure; interpret no flow-based result until restored."
        },
        {
          "control_id": "PC1",
          "control_type": "positive_control",
          "rationale": "A sequenced editing-standard sample checks the amplicon-sequencing assay detects known editing fractions.",
          "expected_result": "Known fractions recovered within the locked tolerance.",
          "failure_implication": "Editing-fraction results uninterpretable until the assay passes."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Active arm improves over both controls, dose-response present, functional endpoints improve, controls pass.",
        "challenges_candidate": "Controls improve equally, or dose-response absent with editing confirmed, or functional endpoints flat while proxies move.",
        "supports_neither_or_mixed": "Both vehicle and editing components present, or an assumption or control fails."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H2",
      "candidate_status": "candidate",
      "assumptions": [
        "Vehicle and inert-locus arms receive the identical injection and handling profile as the active arm."
      ],
      "boundary_conditions": [
        "Effects of the vehicle lot and injection procedure in aged mice of the study strain."
      ],
      "falsifier": {
        "prediction_id": "P2",
        "conditions": "Arm procedures verified identical; primary outcome measured under masking.",
        "observable": "Primary outcome by arm; innate-stimulation and injury markers in the vehicle arm.",
        "incompatible_result": "Vehicle-only shows no improvement while the active arm improves with confirmed on-target editing.",
        "assumption_failure_checks": [
          "Verify vehicle lot and injection logs before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT6",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Vehicle-only and inert-locus arms improve as much as the active arm.",
          "rival_expected": "Controls show no improvement; active arm improves tracking editing fraction.",
          "indeterminate_result": "Partial improvement in controls - mixed mechanism; estimate both components."
        }
      ],
      "nulls": [
        {
          "null_id": "N2",
          "statement": "The population mean change in the primary outcome is equal between vehicle-only and active-editor arms.",
          "analysis_id": "A1",
          "interpretation_limit": "A non-null vehicle contrast coexisting with an editing contrast is a mixed result, not a decision between rivals."
        }
      ],
      "controls": [
        {
          "control_id": "NC-PROCEDURE",
          "control_type": "negative_outcome",
          "rationale": "The negative-control outcome shares the procedure pathway but not innate-stimulation sensitivity.",
          "expected_result": "If the vehicle drives the effect, procedure-linked shifts appear in sensitive readouts; the negative-control outcome stays flat.",
          "failure_implication": "A shift in the negative-control outcome implicates procedure or handling rather than vehicle biology."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Vehicle-only arm improves comparably; markers of innate stimulation or transient injury precede rebound.",
        "challenges_candidate": "Vehicle-only flat while active arm improves with confirmed editing and dose-response.",
        "supports_neither_or_mixed": "Both components present in measurable proportions."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H4",
      "candidate_status": "candidate",
      "assumptions": [
        "Any measurement artifact acts through the acquisition or processing workflow shared by arms or batches."
      ],
      "boundary_conditions": [
        "The antibody lots, panels, and instruments of this study."
      ],
      "falsifier": {
        "prediction_id": "P4",
        "conditions": "Reference beads within tolerance; paired aliquots processed across days and instruments.",
        "observable": "Run-order and batch variance components; paired-aliquot agreement; contrast under balanced reprocessing.",
        "incompatible_result": "Contrast reproduces with processing fully balanced and analyst masked.",
        "assumption_failure_checks": [
          "Verify bead tolerance and instrument calibration before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT7",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Contrast fails to reproduce under balanced masked reprocessing.",
          "rival_expected": "Contrast reproduces and tracks editing fraction.",
          "indeterminate_result": "Batch variance comparable to contrast; power reprocessing before deciding."
        }
      ],
      "nulls": [
        {
          "null_id": "N3",
          "statement": "Run-order and batch components of variance in each subset are zero beyond assay repeatability.",
          "analysis_id": "A3",
          "interpretation_limit": "A bias diagnostic; failure to reject does not certify measurement invariance when precision is insufficient."
        }
      ],
      "controls": [
        {
          "control_id": "NC-QC",
          "control_type": "negative_outcome",
          "rationale": "Reference beads cannot respond to biology but share the acquisition workflow.",
          "expected_result": "Beads stable across arms and batches within tolerance.",
          "failure_implication": "A batch artifact explanation becomes credible until acquisition quality is restored."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Contrast tracks batch or run order; paired aliquots disagree beyond repeatability.",
        "challenges_candidate": "Contrast reproduces balanced and masked; aliquots agree.",
        "supports_neither_or_mixed": "Artifact and real components coexist; report the corrected contrast only."
      },
      "human_review_status": "pending"
    }
  ]
}
